export const sign = (value: number): string => {
  if (value < 0) {
    return "negative";
  } else {
    return "positive";
  }
};

export const check = (value: number): number => {
  if (value < 0) {
    throw new Error("negative");
  } else {
    return value;
  }
};

export const rank = (value: number): number => {
  if (value < 0) {
    return 0;
  } else if (value < 10) {
    return 1;
  } else {
    return 2;
  }
};

